def is_standard_module(modname: str, std_path: Iterable[str] | None = None) -> bool:
    """Try to guess if a module is a standard python module (by default,
    see `std_path` parameter's description).

    :param modname: name of the module we are interested in

    :param std_path: list of path considered has standard. If provided, the old
                    filesystem-based behavior is used. If None, sys.stdlib_module_names
                    is used (or its backport for Python < 3.10).

    :return:
      true if the module:
      - is located on the path listed in one of the directory in `std_path` (if std_path provided)
      - is a standard library module according to sys.stdlib_module_names (if std_path is None)
      - is a built-in module
    """
    modname = modname.split(".")[0]

    # If std_path is provided, use the old filesystem-based behavior
    if std_path is not None:
        try:
            filename = file_from_modpath([modname])
        except ImportError:
            return False
        if filename is None:
            return not util.is_namespace(modname)
        filename = _normalize_path(filename)
        for path in EXT_LIB_DIRS:
            if filename.startswith(_cache_normalize_path(path)):
                return False
        return any(filename.startswith(_cache_normalize_path(path)) for path in std_path)

    # For Python 3.10+, use sys.stdlib_module_names
    if hasattr(sys, 'stdlib_module_names'):
        return modname in sys.stdlib_module_names

    # For Python < 3.10, use our backport
    if sys.version_info[:2] == (3, 9):
        from astroid._backport_stdlib_names import stdlib_module_names
        return modname in stdlib_module_names

    # For Python < 3.9, fall back to old behavior
    return is_standard_module(modname, STD_LIB_DIRS)
